<?php
require_once 'config.php';require_login();expire_manual_requests();$s=db()->prepare("SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0");$s->execute([$_SESSION['user_id']]);$unread=(int)$s->fetchColumn();$groups=db()->query("SELECT g.*,(SELECT COUNT(*) FROM group_members gm WHERE gm.group_id=g.id) member_count,(SELECT COALESCE(SUM(o.price),0) FROM orders o WHERE o.group_id=g.id AND o.status='Active') total FROM app_groups g ORDER BY g.id DESC LIMIT 15")->fetchAll();$s=db()->prepare("SELECT o.*,g.hostel_name,u.name FROM orders o LEFT JOIN app_groups g ON g.id=o.group_id JOIN users u ON u.id=o.user_id WHERE o.user_id=? ORDER BY o.created_at DESC LIMIT 10");$s->execute([$_SESSION['user_id']]);$orders=$s->fetchAll();$pageTitle='Dashboard';require 'header.php';?>
<h1>Welcome, <?=e($_SESSION['user_name'])?></h1><div class="stats"><div class="card"><b><?=count($groups)?></b><span>Recent groups</span></div><div class="card"><b><?=$unread?></b><span>Unread notifications</span></div></div><div class="rowhead"><h2>Recent Groups</h2><a class="btn" href="new_order.php">+ Place Order</a></div><div class="grid"><?php foreach($groups as $g):?><div class="card"><h3>Group-<?=$g['id']?></h3><p><?=e($g['hostel_name'])?> · <?=e($g['app_name'])?></p><p>Status: <b><?=e($g['status'])?></b></p><p>Members: <?=(int)$g['member_count']?> · Total: ₹<?=e(number_format((float)$g['total'],2))?> · Target: ₹<?=e(number_format((float)$g['target_threshold'],2))?></p><a href="group.php?id=<?=(int)$g['id']?>">View group →</a></div><?php endforeach;if(!$groups):?><div class="card">Abhi koi group nahi bana. Pehla order place karein.</div><?php endif;?></div><h2>Your recent purchases</h2><div class="card tablewrap"><?php if(!$orders):?>No orders yet.<?php else:?><table><tr><th>Hostel</th><th>App</th><th>Amount</th><th>Group</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['hostel_name']??'')?></td><td><?=e($o['app_name'])?></td><td>₹<?=e(number_format((float)$o['price'],2))?></td><td><?php if($o['group_id']):?><a href="group.php?id=<?=(int)$o['group_id']?>">Group-<?=$o['group_id']?></a><?php endif;?></td></tr><?php endforeach;?></table><?php endif;?></div><?php require 'footer.php';?>
